/**
 * Runtime access to the body binding index.
 *
 * The index is generated by scripts/build-body-bindings.mjs and served from
 * /body-models/bindings.json. It is fetched rather than imported so it never
 * enters the JavaScript bundle: the body page already defers a large anatomy
 * model, and 135 KB of lookup table has no business loading for a reader who
 * never selects a structure.
 *
 * Rows are stored once and referenced by index in the generated file, so this
 * module's job is to rehydrate them into objects and answer two questions:
 * what does Kamura have for this exact structure, and what does it have for the
 * system that structure belongs to.
 */

import type {SystemId} from '@/components/body-explorer/anatomy';

export interface OutcomeRow {
  slug: string;
  treatment: string;
  outcome: string;
  grade: 'A' | 'B' | 'C' | 'D' | 'F';
  direction: 'positive' | 'neutral' | 'negative';
  category: string;
}
export interface TherapyRow {id: string; name: string; kind: string; region: string}
export interface ToolRow {kind: 'instrument' | 'compounded'; slug: string; basis: string}
export interface AnalyteRow {label: string; basis: string}

interface RawIndex {
  generated: string;
  anchors: Record<string, string>;
  counts: {anatomical: number; cellular: number; informational: number; unmapped: number};
  outcomes: Record<string, {kind: string; systems: SystemId[]; anchors: string[]}>;
  rows: [string, string, string, string, string, string][];
  bySystem: Record<string, number[]>;
  byAnchor: Record<string, number[]>;
  therapiesBySystem: Record<string, TherapyRow[]>;
  therapiesByAnchor: Record<string, TherapyRow[]>;
  toolsByAnchor: Record<string, ToolRow[]>;
  toolsBySystem: Record<string, ToolRow[]>;
  analytesByAnchor: Record<string, AnalyteRow[]>;
}

export interface BodyIndex {
  generated: string;
  counts: RawIndex['counts'];
  /** Evidence for one exact structure, by FMA concept id. */
  forConcept(conceptId: string): StructureEvidence;
  /** Evidence for a whole system, used when a structure has nothing of its own. */
  forSystem(system: SystemId): StructureEvidence;
}

export interface StructureEvidence {
  outcomes: OutcomeRow[];
  therapies: TherapyRow[];
  tools: ToolRow[];
  analytes: AnalyteRow[];
  /** True when at least one of the four lists has something in it. */
  any: boolean;
}

const EMPTY: StructureEvidence = {outcomes: [], therapies: [], tools: [], analytes: [], any: false};

const GRADE_ORDER = {A: 0, B: 1, C: 2, D: 3, F: 4} as const;

function build(raw: RawIndex): BodyIndex {
  const rows: OutcomeRow[] = raw.rows.map(([slug, treatment, outcome, grade, direction, category]) => ({
    slug, treatment, outcome,
    grade: grade as OutcomeRow['grade'],
    direction: direction as OutcomeRow['direction'],
    category,
  }));

  const resolve = (
    outcomeIdx: number[] | undefined,
    therapies: TherapyRow[] | undefined,
    tools: ToolRow[] | undefined,
    analytes: AnalyteRow[] | undefined,
  ): StructureEvidence => {
    const outcomes = (outcomeIdx ?? []).map((i) => rows[i]).filter(Boolean)
      .sort((a, b) => GRADE_ORDER[a.grade] - GRADE_ORDER[b.grade]);
    const t = therapies ?? [];
    const k = tools ?? [];
    const a = analytes ?? [];
    return {outcomes, therapies: t, tools: k, analytes: a,
      any: outcomes.length > 0 || t.length > 0 || k.length > 0 || a.length > 0};
  };

  return {
    generated: raw.generated,
    counts: raw.counts,
    forConcept: (id) => resolve(raw.byAnchor[id], raw.therapiesByAnchor[id], raw.toolsByAnchor[id], raw.analytesByAnchor[id]),
    forSystem: (s) => resolve(raw.bySystem[s], raw.therapiesBySystem[s], raw.toolsBySystem[s], undefined),
  };
}

let cache: Promise<BodyIndex> | null = null;

/**
 * Load the index, once per page. Rejection is the caller's to handle — the body
 * page stays usable without it, it just cannot answer what it has for a part.
 */
export function loadBodyIndex(signal?: AbortSignal): Promise<BodyIndex> {
  if (!cache) {
    cache = fetch('/body-models/bindings.json', {signal})
      .then((r) => {
        if (!r.ok) throw new Error('Evidence links could not be loaded.');
        return r.json() as Promise<RawIndex>;
      })
      .then(build)
      .catch((e) => {
        cache = null; // let a later selection retry rather than fail forever
        throw e;
      });
  }
  return cache;
}

export {EMPTY as EMPTY_EVIDENCE};
